body:
I'm working with a pre-exsiting renderer that relies on setting constants and binding resources within in the same struct. The below example shader will fail in DXC with this error `error: Index for resource array inside cbuffer must be a literal expression`

I can see here https://github.com/microsoft/DirectXShaderCompiler/blob/81ef064a47a191c9fc68a43adca4706244c3687b/lib/HLSL/HLOperationLower.cpp#L368 that this appears to be unsupported behavior? However FXC can compile this same shader without use as long as the loop is marked with `unroll`. Is anyone tracking or sitting on a branch with a fix for this? If not, any guidance for us to make a local change would be appreciated.

- This occurs on main as well as in the July 2022 official release
- /HV 2016 has no impact
- `dxc.exe /E psMain /T ps_6_6`

```
struct FooBarInfo
{
    float Scalar;
    Texture2D<float4> Texture[4];
};

cbuffer cbFooBar
{
    FooBarInfo        FooBars[4];
    Texture2D<float4> FooBarTextures[4];
};

Texture2D<float4> NotFooBarTextures[4];

float4 psMain() : SV_TARGET0
{
    float4 foo_bar_color = float4( 0.0, 0.0, 0.0, 0.0 );

    [unroll]
    for( int i = 0; i < 4; ++i )
    {
        FooBarInfo        foo_bar     = FooBars          [ i ];
        Texture2D<float4> foo_bar_tex = foo_bar.Texture  [ i ]; // (Works in FXC only) error: Index for resource array inside cbuffer must be a literal expression
     // Texture2D<float4> foo_bar_tex = FooBarTextures   [ i ]; // (Works in FXC only) error: Index for resource array inside cbuffer must be a literal expression
     // Texture2D<float4> foo_bar_tex = NotFooBarTextures[ i ]; // Works in DXC & FXC but doesn't work with our shader resource binding system

        foo_bar_color += foo_bar_tex[int2(0,0)] * foo_bar.Scalar;
    }

    return foo_bar_color;
}
```
